nextflow_process {

    name "Test Process DSHBIO_SPLITBED"
    script "../main.nf"
    process "DSHBIO_SPLITBED"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "dshbio"
    tag "dshbio/splitbed"

    test("test-dshbio-splitbed") {

        when {
            params{
                module_args = '--records 2'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
				    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/multi_intervals.bed', checkIfExists: true)
				]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("test-dshbio-splitbed-stub") {
        options '-stub'

        when {
            params{
                module_args = '--records 2'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
				    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/multi_intervals.bed', checkIfExists: true)
				]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

}
